import java.util.*;

class Solution {
  public int maxIncreasingCells(int[][] mat) {
    int m = mat.length, n = mat[0].length;
    int[][] cells = new int[m * n][3];
    int p = 0;
    for (int i = 0; i < m; i++)
      for (int j = 0; j < n; j++) {
        cells[p++] = new int[] {mat[i][j], i, j};
      }
    Arrays.sort(cells, Comparator.comparingInt(a -> a[0]));
    int[] row = new int[m], col = new int[n];
    int ans = 0;
    for (int i = 0; i < cells.length; ) {
      int j = i;
      while (j < cells.length && cells[j][0] == cells[i][0]) j++;
      int[] best = new int[j - i];
      for (int q = i; q < j; q++) best[q - i] = Math.max(row[cells[q][1]], col[cells[q][2]]) + 1;
      for (int q = i; q < j; q++) {
        int v = best[q - i];
        row[cells[q][1]] = Math.max(row[cells[q][1]], v);
        col[cells[q][2]] = Math.max(col[cells[q][2]], v);
        ans = Math.max(ans, v);
      }
      i = j;
    }
    return ans;
  }
}
